import json
from pathlib import Path


data_dir = Path(__file__).resolve().parents[1] / "data"
albums = json.loads((data_dir / "albums.json").read_text(encoding="utf-8-sig"))
if not isinstance(albums, list):
    raise ValueError("albums.json must contain an array")

output = data_dir / "albums.local.js"
output.write_text(
    "// Generated by tools/sync-local-albums.py from data/albums.json.\n"
    "window.albumCornerLocalAlbums = " + json.dumps(albums, ensure_ascii=False, indent=2) + ";\n",
    encoding="utf-8",
    newline="\n",
)
